{
  "implementation": "def solve(case):
    payload = case['payload']
    nodes = payload['nodes']
    required_symbols = set(payload['required_symbols'])

    # Build indexes
    node_by_id = {}
    parent_to_children = {}
    for node in nodes:
        nid = node['id']
        node_by_id[nid] = node
        parent = node.get('parent')
        if parent is not None:
            parent_to_children.setdefault(parent, []).append(nid)

    # Precompute subtree node sets (including the node itself)
    subtree_nodes = {}
    def compute_subtree(nid):
        if nid in subtree_nodes:
            return subtree_nodes[nid]
        result = {nid}
        children = parent_to_children.get(nid, [])
        for c in children:
            result |= compute_subtree(c)
        subtree_nodes[nid] = result
        return result
    for nid in node_by_id:
        compute_subtree(nid)

    # Sort nodes: depth descending, then id ascending (string comparison)
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))

    retained = set(node_by_id.keys())
    removal_order = []

    for node in sorted_nodes:
        nid = node['id']
        parent = node.get('parent')
        # Cannot remove root
        if parent is None:
            continue
        if not node['removable']:
            continue
        # Cannot remove if any child is still retained
        children = parent_to_children.get(nid, [])
        if any(c in retained for c in children):
            continue
        # Check required symbols after removal
        sub = subtree_nodes[nid]
        new_retained = retained - sub
        ok = True
        for sym in required_symbols:
            found = False
            for rid in new_retained:
                if node_by_id[rid]['symbol'] == sym:
                    found = True
                    break
            if not found:
                ok = False
                break
        if ok:
            retained = new_retained
            removal_order.append(nid)

    retained_ids = sorted(retained)
    return {'retained_ids': retained_ids, 'removal_order': removal_order}
